CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_birth_date`(p_min_age INT, p_max_age INT) RETURNS date
    NO SQL
BEGIN
    DECLARE v_oldest   DATE;   
    DECLARE v_youngest DATE;   
    SET v_oldest   = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL (p_max_age + 1) YEAR), INTERVAL 1 DAY);
    SET v_youngest = DATE_SUB(CURDATE(), INTERVAL p_min_age YEAR);
    RETURN DATE_ADD(v_oldest, INTERVAL fn_gen_random_int(0, DATEDIFF(v_youngest, v_oldest)) DAY);
END ;;

