CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_is_active`(p_index INT, p_total INT, p_active_pct DECIMAL(5,2)) RETURNS tinyint
    NO SQL
    DETERMINISTIC
BEGIN
    DECLARE v_active_total BIGINT;
    SET v_active_total = CAST(ROUND(p_total * p_active_pct / 100) AS SIGNED);
    RETURN IF((p_index * v_active_total) DIV p_total > ((p_index - 1) * v_active_total) DIV p_total, 1, 0);
END ;;

