CREATE DEFINER=`jose.amaro`@`%` PROCEDURE `sp_gen_validate_params`(
    IN p_total      INT,
    IN p_country    CHAR(2),
    IN p_min_age    INT,
    IN p_max_age    INT,
    IN p_active_pct DECIMAL(5,2)
)
BEGIN
    IF p_total IS NULL OR p_total < 1 OR p_total > 100000 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_total debe estar entre 1 y 100000';
    END IF;
    IF p_min_age IS NULL OR p_max_age IS NULL OR p_min_age < 18 OR p_max_age > 100 OR p_min_age > p_max_age THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Edades invalidas: se requiere 18 <= p_min_age <= p_max_age <= 100';
    END IF;
    IF p_active_pct IS NULL OR p_active_pct < 0 OR p_active_pct > 100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_active_pct debe estar entre 0 y 100';
    END IF;
    IF p_country IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM tbc_gen_country_profile WHERE country_code = p_country AND status = 1)
           OR NOT EXISTS (SELECT 1 FROM tbc_gen_given_names  WHERE country_code = p_country AND gender_ID = 1)
           OR NOT EXISTS (SELECT 1 FROM tbc_gen_given_names  WHERE country_code = p_country AND gender_ID = 2)
           OR NOT EXISTS (SELECT 1 FROM tbc_gen_family_names WHERE country_code = p_country) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El pais no existe, esta deshabilitado o no tiene catalogo de nombres';
        END IF;
    ELSEIF NOT EXISTS (SELECT 1 FROM tbc_gen_country_profile WHERE status = 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay paises habilitados en tbc_gen_country_profile';
    END IF;
END ;;

